-- HR and payroll workflows: module settings, loans and advances, leave encashment, service book, two-step leave approval, requisition approval, payroll verify/bank file/publish.
CREATE TABLE IF NOT EXISTS "hr_settings" (tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE, employee_series jsonb NOT NULL, payslip_series jsonb NOT NULL, leave_levels smallint NOT NULL DEFAULT 1, encashment jsonb NOT NULL, attendance jsonb NOT NULL, loans jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());--> statement-breakpoint
ALTER TABLE "hr_settings" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS tenant_isolation ON "hr_settings";--> statement-breakpoint
CREATE POLICY tenant_isolation ON "hr_settings" USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
DO $$ BEGIN IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'zynetix_app') THEN GRANT SELECT, INSERT, UPDATE, DELETE ON "hr_settings" TO zynetix_app; END IF; END $$;--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "staff_loans" (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, loan_no text NOT NULL, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, amount_paise bigint NOT NULL, installments smallint NOT NULL, emi_paise bigint NOT NULL, start_month text NOT NULL, purpose text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending', decided_by uuid REFERENCES users(id) ON DELETE SET NULL, decided_at timestamptz, decision_note text, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (tenant_id, loan_no));--> statement-breakpoint
ALTER TABLE "staff_loans" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS tenant_isolation ON "staff_loans";--> statement-breakpoint
CREATE POLICY tenant_isolation ON "staff_loans" USING (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK (tenant_id = nullif(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
DO $$ BEGIN IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'zynetix_app') THEN GRANT SELECT, INSERT, UPDATE, DELETE ON "staff_loans" TO zynetix_app; END IF; END $$;--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "leave_encashments" (id uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, leave_type_id uuid NOT NULL REFERENCES leave_types(id), year smallint NOT NULL, days numeric(5,1) NOT NULL, amount_paise bigint NOT NULL, pay_month text NOT NULL, status text NOT NULL DEFAULT 'pending', adjustment_id uuid REFERENCES payroll_adjustments(id) ON DELETE SET NULL, decided_by uuid REFERENCES users(id) ON DELETE SET NULL, decided_at timestamptz, decision_note text, created_by uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());--> statement-breakpoint
