ALTER TABLE payroll_runs ADD COLUMN IF NOT EXISTS verified_by uuid REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS verified_at timestamptz, ADD COLUMN IF NOT EXISTS bank_file_at timestamptz, ADD COLUMN IF NOT EXISTS published_by uuid REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS published_at timestamptz;--> statement-breakpoint
ALTER TABLE payslips ADD COLUMN IF NOT EXISTS payslip_no text;--> statement-breakpoint
ALTER TABLE payroll_adjustments ADD COLUMN IF NOT EXISTS loan_id uuid REFERENCES staff_loans(id) ON DELETE CASCADE;--> statement-breakpoint
ALTER TABLE leave_types ADD COLUMN IF NOT EXISTS encashable boolean NOT NULL DEFAULT false;--> statement-breakpoint
ALTER TABLE leave_requests ADD COLUMN IF NOT EXISTS recommended_by uuid REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS recommended_at timestamptz, ADD COLUMN IF NOT EXISTS recommend_note text;--> statement-breakpoint
ALTER TABLE job_openings ADD COLUMN IF NOT EXISTS justification text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS approved_by uuid REFERENCES users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS approved_at timestamptz, ADD COLUMN IF NOT EXISTS decision_note text;
